"""Tests for fmea_needs_to_trlc."""

import json
import os
import tempfile
import unittest

from fmea_needs_to_trlc import ConversionError, convert, main

API_TRLC = """// GENERATED by puml_cli from public API class diagrams -- do not edit
package lib_api

import ScoreReq

ScoreReq.ApiMethod lib_Bits_SetBit {
  diagram = "public_api.puml"
  line = 3
  signatures = ["`bool lib::Bits::SetBit(T value, std::size_t position)`"]
}

ScoreReq.ApiMethod lib_Bits_operator_bitor {
  diagram = "public_api.puml"
  line = 4
  signatures = ["`T lib::Bits::operator|(T lhs, T rhs)`"]
}
"""


def _fmea(**overrides):
    need = {
        "type": "comp_saf_fmea",
        "title": "Bits no return",
        "content": 'Covered by the "error reaction" AoU.',
        "fault_id": "MF_01_01,MF_01_06,CO_01_02",
        "failure_effect": "The bit is not set, so the caller may work on stale data.",
        "violates": ["comp_arc_sta__lib__bits[version==1]", "real_arc_int_op__lib__set_bit[version==1]"],
        "status": "valid",
        "version": 3,
        "docname": "safety_analysis/fmea",
        "doctype": ".rst",
        "lineno": 7,
    }
    need.update(overrides)
    return need


NEEDS = {
    "comp_arc_sta__lib__bits": {"type": "comp_arc_sta", "title": "Bits", "safety": "ASIL_B"},
    "real_arc_int__lib__bits": {"type": "real_arc_int", "title": "Bits", "safety": "ASIL_B"},
    "real_arc_int_op__lib__set_bit": {
        "type": "real_arc_int_op",
        "title": "SetBit",
        "included_by": ["real_arc_int__lib__bits"],
        "safety": "ASIL_B",
    },
    "real_arc_int_op__lib__op_or": {
        "type": "real_arc_int_op",
        "title": "operator|",
        "included_by": ["real_arc_int__lib__bits"],
        "safety": "QM",
    },
}


class FmeaNeedsToTrlcTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.api = os.path.join(self.tmp.name, "public_api.trlc")
        with open(self.api, "w", encoding="utf-8") as f:
            f.write(API_TRLC)

    def _needs_file(self, **fmeas):
        path = os.path.join(self.tmp.name, "needs.json")
        needs = dict(NEEDS, **fmeas)
        with open(path, "w", encoding="utf-8") as f:
            json.dump({"current_version": "1", "versions": {"1": {"needs": needs}}}, f)
        return path

    def _convert(self, **fmeas):
        return convert([self._needs_file(**fmeas)], [self.api], "LibFmea")

    def test_record_maps_the_fmea_fields(self):
        text, count = self._convert(comp_saf_fmea__lib__no_return=_fmea())
        self.assertEqual(1, count)
        self.assertIn("package LibFmea\n\nimport ScoreReq\nimport lib_api\n", text)
        self.assertIn("// safety_analysis/fmea.rst:7\nScoreReq.FailureMode comp_saf_fmea__lib__no_return {", text)
        self.assertIn('  description = "Bits no return"', text)
        self.assertIn('  note = "Covered by the \\"error reaction\\" AoU."', text)
        self.assertIn('  failureeffect = "The bit is not set, so the caller may work on stale data."', text)
        self.assertIn(
            "  guidewords = [ScoreReq.Guideword.LossOfFunction, ScoreReq.Guideword.TooLate]",
            text,
        )
        self.assertIn("  interface = [lib_api.lib_Bits_SetBit]", text)
        self.assertIn("  safety = ScoreReq.Asil.B", text)
        self.assertIn("  version = 3", text)

    def test_operator_titles_resolve_to_their_api_method(self):
        text, _ = self._convert(
            comp_saf_fmea__lib__wrong=_fmea(violates=["real_arc_int_op__lib__op_or", "real_arc_int_op__lib__set_bit"])
        )
        self.assertIn("  interface = [lib_api.lib_Bits_operator_bitor, lib_api.lib_Bits_SetBit]", text)

    def test_safety_is_the_highest_of_the_violated_needs(self):
        text, _ = self._convert(
            comp_saf_fmea__lib__wrong=_fmea(violates=["real_arc_int_op__lib__op_or", "real_arc_int_op__lib__set_bit"])
        )
        self.assertIn("  safety = ScoreReq.Asil.B", text)

    def test_own_safety_wins(self):
        text, _ = self._convert(comp_saf_fmea__lib__no_return=_fmea(safety="QM"))
        self.assertIn("  safety = ScoreReq.Asil.QM", text)

    def test_architecture_only_fmea_has_no_interface(self):
        text, _ = self._convert(comp_saf_fmea__lib__no_return=_fmea(violates=["comp_arc_sta__lib__bits"]))
        self.assertNotIn("interface", text)
        self.assertNotIn("import lib_api", text)

    def test_invalid_needs_are_skipped(self):
        text, count = self._convert(comp_saf_fmea__lib__no_return=_fmea(status="invalid"))
        self.assertEqual(0, count)
        self.assertNotIn("ScoreReq.FailureMode", text)
        self.assertNotIn("import ScoreReq", text)

    def test_unknown_fault_id_fails(self):
        with self.assertRaisesRegex(ConversionError, "unknown fault_id 'XX_01_01'"):
            self._convert(comp_saf_fmea__lib__no_return=_fmea(fault_id="XX_01_01"))

    def test_operation_missing_in_the_public_api_fails(self):
        needs = dict(NEEDS)
        needs["real_arc_int_op__lib__set_bit"] = dict(NEEDS["real_arc_int_op__lib__set_bit"], title="SetBits")
        path = os.path.join(self.tmp.name, "needs.json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump({"current_version": "1", "versions": {"1": {"needs": dict(needs, x=dict(_fmea(), id="x"))}}}, f)
        with self.assertRaisesRegex(ConversionError, r"no ApiMethod of the public API declares 'Bits::SetBits\('"):
            convert([path], [self.api], "LibFmea")

    def test_unsupported_asil_fails(self):
        with self.assertRaisesRegex(ConversionError, "safety 'ASIL_A'"):
            self._convert(comp_saf_fmea__lib__no_return=_fmea(safety="ASIL_A"))

    def test_main_writes_the_trlc_file(self):
        out = os.path.join(self.tmp.name, "out.trlc")
        needs = self._needs_file(comp_saf_fmea__lib__no_return=_fmea())
        self.assertEqual(0, main([needs, "--package", "LibFmea", "--api-trlc", self.api, "--out", out]))
        with open(out, encoding="utf-8") as f:
            self.assertIn("ScoreReq.FailureMode comp_saf_fmea__lib__no_return", f.read())

    def test_main_reports_conversion_errors(self):
        out = os.path.join(self.tmp.name, "out.trlc")
        needs = self._needs_file(comp_saf_fmea__lib__no_return=_fmea(failure_effect=""))
        self.assertEqual(1, main([needs, "--package", "LibFmea", "--api-trlc", self.api, "--out", out]))


if __name__ == "__main__":
    unittest.main()
